using System;
using System.Collections.Generic;
using UnityEngine;

// Literal topology operations from immutable v11 compose_reference4_optimal_v9.
// Arrays use logical top-down row-major order. No geometry, palette or temporal edits.
public static class OriginalOps364 {
 public static bool[] Copy(bool[] a)=>(bool[])a.Clone();
 public static void Hand(bool[] m,int w,int h){for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){int i=y*w+x;if(m[i]&&!m[i-1]&&!m[i+1])m[i]=false;}}
 public static void Endpoints(bool[] m,int w,int h,int start,int stop){for(int y=start;y<stop;y++){if(y<=0||y>=h-1)continue;Bounds(m,w,y,out int l,out int r);Bounds(m,w,y-1,out int p,out int q);Bounds(m,w,y+1,out int n,out int z);if(l<0||p<0||n<0)continue;if(l<p&&l<n)m[y*w+l]=false;if(r>q&&r>z)m[y*w+r]=false;}}
 public static void Bounds(bool[] m,int w,int y,out int l,out int r){l=-1;r=-1;for(int x=0;x<w;x++)if(m[y*w+x]){if(l<0)l=x;r=x;}}
 public static bool[] Close3(bool[] m,int w,int h){var d=new bool[m.Length];var e=new bool[m.Length];for(int y=0;y<h;y++)for(int x=0;x<w;x++){bool v=false;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;if(xx>=0&&xx<w&&yy>=0&&yy<h&&m[yy*w+xx])v=true;}d[y*w+x]=v;}for(int y=0;y<h;y++)for(int x=0;x<w;x++){bool v=true;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;if(xx>=0&&xx<w&&yy>=0&&yy<h&&!d[yy*w+xx])v=false;}e[y*w+x]=v;}return e;}
 public sealed class Components{public int[]labels,sizes;public int count;}
 public static Components Label(bool[] m,int w,int h,int connectivity){var labels=new int[m.Length];var sizes=new List<int>{0};var queue=new int[m.Length];int lab=0;for(int start=0;start<m.Length;start++){if(!m[start]||labels[start]!=0)continue;lab++;int front=0,back=0;queue[back++]=start;labels[start]=lab;while(front<back){int i=queue[front++],x=i%w,y=i/w;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){if(dx==0&&dy==0||connectivity==4&&Math.Abs(dx)+Math.Abs(dy)!=1)continue;int xx=x+dx,yy=y+dy;if(xx<0||xx>=w||yy<0||yy>=h)continue;int j=yy*w+xx;if(m[j]&&labels[j]==0){labels[j]=lab;queue[back++]=j;}}}sizes.Add(back);}return new Components{labels=labels,sizes=sizes.ToArray(),count=lab};}
 public static bool[] Largest8(bool[] m,int w,int h){var cc=Label(m,w,h,8);if(cc.count==0)return Copy(m);int largest=1;for(int k=2;k<=cc.count;k++)if(cc.sizes[k]>cc.sizes[largest])largest=k;var o=new bool[m.Length];for(int i=0;i<o.Length;i++)o[i]=cc.labels[i]==largest;return o;}
 public static void HairEndpoints(bool[] m,int w,int h){int lo=h,hi=-1;for(int i=0;i<m.Length;i++)if(m[i]){lo=Math.Min(lo,i/w);hi=Math.Max(hi,i/w);}if(hi<0){lo=0;hi=50;}Endpoints(m,w,h,lo+2,hi-1);}
 public static bool[] Leg(bool[] suppliedRaw,bool[] skirt,int w,int h,out bool[] trimmed,out bool[] smoothed){var raw=Copy(suppliedRaw);int top=h;for(int i=0;i<skirt.Length;i++)if(skirt[i])top=Math.Min(top,i/w);bool hasSkirt=top<h;if(!hasSkirt)top=0;if(hasSkirt)for(int y=0;y<Math.Min(h,Math.Max(0,top+2));y++)Array.Clear(raw,y*w,w);trimmed=Copy(raw);var ys=new List<int>();var left=new List<float>();var right=new List<float>();for(int y=Math.Max(0,top+2);y<h;y++){Bounds(raw,w,y,out int l,out int r);int n=0;for(int x=0;x<w;x++)if(raw[y*w+x])n++;if(n>=2){ys.Add(y);left.Add(l);right.Add(r);}}var result=new bool[raw.Length];if(ys.Count>=6){for(int n=0;n<ys.Count;n++){int a=Math.Max(0,n-2),b=Math.Min(ys.Count,n+3);float l=0,r=0;for(int k=a;k<b;k++){l+=left[k];r+=right[k];}l/=(b-a);r/=(b-a);if(Math.Abs(l-left[n])>1)l=left[n];if(Math.Abs(r-right[n])>1)r=right[n];int li=Math.Max(0,(int)Math.Round((double)l,MidpointRounding.ToEven)),ri=Math.Min(w-1,(int)Math.Round((double)r,MidpointRounding.ToEven));if(ri>=li)for(int x=li;x<=ri;x++)result[ys[n]*w+x]=true;}}else result=Copy(raw);smoothed=Copy(result);for(int x=0;x<w;x++){int bottom=-1,first=h;for(int y=0;y<h;y++){if(skirt[y*w+x])bottom=y;if(result[y*w+x])first=Math.Min(first,y);}if(bottom>=0&&first<h&&first>bottom&&first-bottom<=5)for(int y=bottom;y<=first;y++)result[y*w+x]=true;}return result;}
 public sealed class RepairResult{public bool[]foreground,external,outline,cleaned;public int[]owner;public Color[]colour;public float[]depth;}
 public static RepairResult Repair(int[] suppliedOwner,Color[] suppliedColour,float[] suppliedDepth,int w,int h){var owner=(int[])suppliedOwner.Clone();var colour=(Color[])suppliedColour.Clone();var depth=(float[])suppliedDepth.Clone();var fg=new bool[owner.Length];var bg=new bool[owner.Length];for(int i=0;i<owner.Length;i++){fg[i]=owner[i]>0;bg[i]=!fg[i];}var cc=Label(bg,w,h,4);int exteriorLabel=cc.labels[0];var ext=new bool[owner.Length];for(int i=0;i<ext.Length;i++)ext[i]=cc.labels[i]==exteriorLabel;for(int i=0;i<owner.Length;i++){if(fg[i]||ext[i])continue;int area=cc.sizes[cc.labels[i]];if(area<=2){int x=i%w,y=i/w;int[] candidates={y>0?i-w:-1,y<h-1?i+w:-1,x>0?i-1:-1,x<w-1?i+1:-1};foreach(int j in candidates)if(j>=0&&owner[j]>0){colour[i]=colour[j];owner[i]=owner[j];fg[i]=true;break;}}else ext[i]=true;}
 var outline=new bool[owner.Length];for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){int i=y*w+x;if(fg[i]&&(ext[i-w]||ext[i+w]||ext[i-1]||ext[i+1]))outline[i]=true;}var clean=Copy(outline);for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){int i=y*w+x;if(!outline[i])continue;if(outline[i-w]&&outline[i+1]&&!ext[i+w-1]||outline[i-w]&&outline[i-1]&&!ext[i+w+1]||outline[i+w]&&outline[i+1]&&!ext[i-w-1]||outline[i+w]&&outline[i-1]&&!ext[i-w+1])clean[i]=false;}return new RepairResult{owner=owner,colour=colour,depth=depth,foreground=fg,external=ext,outline=outline,cleaned=clean};}
}
